const SUPPORTED_INSTAGRAM_WEBHOOK_OBJECTS = new Set(["instagram", "page"]);

const IG_ACCOUNT_SELECT =
  "organization_id, page_access_token, instagram_username, instagram_name, instagram_business_account_id, facebook_page_id, threads_user_id, threads_username, has_threads";

async function lookupInstagramAccountByField(
  supabase: ReturnType<typeof createClient>,
  field: "instagram_business_account_id" | "facebook_page_id",
  value: string,
): Promise<InstagramWebhookAccount | null> {
  const { data, error } = await supabase
    .from("organization_instagram_accounts")
    .select(IG_ACCOUNT_SELECT)
    .eq(field, value)
    .eq("is_active", true)
    .limit(1)
    .maybeSingle();
  if (error) {
    console.error(`[instagram-webhook] account lookup by ${field} error:`, error.message);
  }
  return data ? (data as InstagramWebhookAccount) : null;
}

/** Prefer recipient.id (inbox owner) when org has multiple IG accounts sharing one Threads profile. */
async function resolveInstagramAccountForMessaging(
  supabase: ReturnType<typeof createClient>,
  entryId: string | null,
  recipientId: string | null,
  senderId: string | null = null,
): Promise<InstagramWebhookAccount | null> {
  const recipient = recipientId?.trim() ?? "";
  const entry = entryId?.trim() ?? "";
  const sender = senderId?.trim() ?? "";

  if (recipient) {
    const byRecipient = await lookupInstagramAccountByField(
      supabase,
      "instagram_business_account_id",
      recipient,
    );
    if (byRecipient) {
      console.log("[instagram-webhook] matched account via recipient.id:", recipient);
      return byRecipient;
    }
  }

  if (sender) {
    const bySender = await lookupInstagramAccountByField(
      supabase,
      "instagram_business_account_id",
      sender,
    );
    if (bySender) {
      console.log("[instagram-webhook] matched account via sender.id (business):", sender);
      return bySender;
    }
  }

  if (entry) {
    const byIg = await lookupInstagramAccountByField(
      supabase,
      "instagram_business_account_id",
      entry,
    );
    if (byIg) return byIg;

    const byPage = await lookupInstagramAccountByField(supabase, "facebook_page_id", entry);
    if (byPage) {
      console.log("[instagram-webhook] matched account via facebook_page_id:", entry);
      return byPage;
    }

    const { data: byThreadsList, error: byThreadsErr } = await supabase
      .from("organization_instagram_accounts")
      .select(IG_ACCOUNT_SELECT)
      .eq("threads_user_id", entry)
      .eq("is_active", true)
      .eq("has_threads", true);
    if (byThreadsErr) {
      console.error("[instagram-webhook] account lookup by threads_user_id error:", byThreadsErr.message);
    }
    const threadsMatches = (byThreadsList ?? []) as InstagramWebhookAccount[];
    if (threadsMatches.length === 1) {
      console.log("[instagram-webhook] matched account via threads_user_id:", entry);
      return threadsMatches[0];
    }
    if (threadsMatches.length > 1) {
      if (recipient) {
        const disambiguated = threadsMatches.find(
          (row) => String(row.instagram_business_account_id).trim() === recipient,
        );
        if (disambiguated) {
          console.log("[instagram-webhook] disambiguated shared threads_user_id via recipient:", recipient);
          return disambiguated;
        }
      }
      if (sender) {
        const bySenderBiz = threadsMatches.find(
          (row) => String(row.instagram_business_account_id).trim() === sender,
        );
        if (bySenderBiz) {
          console.log("[instagram-webhook] disambiguated shared threads_user_id via sender.id:", sender);
          return bySenderBiz;
        }
      }
      console.warn(
        "[instagram-webhook] ambiguous threads_user_id entry — multiple IG accounts; need recipient/sender.id",
        {
          entryId: entry,
          recipientId: recipient || null,
          senderId: sender || null,
          accounts: threadsMatches.map((row) => row.instagram_username ?? row.instagram_business_account_id),
        },
      );
      return null;
    }
  }

  const { data: singleAccount } = await supabase
    .from("organization_instagram_accounts")
    .select(IG_ACCOUNT_SELECT)
    .eq("is_active", true)
    .limit(1)
    .maybeSingle();
  if (singleAccount) {
    console.log("[instagram-webhook] using single active account fallback");
    return singleAccount as InstagramWebhookAccount;
  }
  return null;
}

/** Echo DMs to another connected IG account often use the contact IGSID as recipient.id, not business account id. */
async function resolveEchoBridgeInboxAccount(
  supabase: ReturnType<typeof createClient>,
  senderAccount: InstagramWebhookAccount,
  recipientId: string,
): Promise<InstagramWebhookAccount | null> {
  const rid = recipientId.trim();
  if (!rid) return null;

  const byBiz = await lookupInstagramAccountByField(
    supabase,
    "instagram_business_account_id",
    rid,
  );
  if (byBiz && byBiz.organization_id === senderAccount.organization_id) {
    return byBiz;
  }

  const senderBizId = String(senderAccount.instagram_business_account_id).trim();
  const { data: crossConv } = await supabase
    .from("instagram_conversations")
    .select("customer_name")
    .eq("organization_id", senderAccount.organization_id)
    .eq("instagram_business_account_id", senderBizId)
    .eq("customer_ig_id", rid)
    .maybeSingle();

  if (!crossConv) return null;

  const customerName = (crossConv as { customer_name?: string | null }).customer_name?.trim() ?? "";
  const { data: siblings } = await supabase
    .from("organization_instagram_accounts")
    .select(IG_ACCOUNT_SELECT)
    .eq("organization_id", senderAccount.organization_id)
    .eq("is_active", true);

  for (const row of siblings ?? []) {
    const sibling = row as InstagramWebhookAccount;
    const siblingBizId = String(sibling.instagram_business_account_id).trim();
    if (siblingBizId === senderBizId) continue;
    const uname = sibling.instagram_username?.trim();
    if (uname && customerName.toLowerCase() === `@${uname.toLowerCase()}`) {
      console.log("[instagram-webhook] echo bridge inbox via cross-conversation IGSID", {
        recipientIgsid: rid,
        inbox: uname,
      });
      return sibling;
    }
  }

  const fallback = (siblings ?? []).find((row) => {
    const sibling = row as InstagramWebhookAccount;
    return String(sibling.instagram_business_account_id).trim() !== senderBizId;
  }) as InstagramWebhookAccount | undefined;

  if (fallback && (siblings ?? []).length === 2) {
    console.log("[instagram-webhook] echo bridge inbox via sibling fallback", {
      recipientIgsid: rid,
      inbox: fallback.instagram_username,
    });
    return fallback;
  }

  return null;
}

type ExistingInstagramConvRow = {
  id: string;
  first_inbound_at: string | null;
  customer_name: string | null;
  customer_ig_id: string;
};

async function findExistingInstagramConversation(
  supabase: ReturnType<typeof createClient>,
  orgId: string,
  inboxBusinessAccountId: string,
  customerMessagingId: string,
  senderId: string,
  customerName: string | null,
): Promise<ExistingInstagramConvRow | null> {
  const tryIds = [...new Set([customerMessagingId.trim(), senderId.trim()].filter(Boolean))];
  const matches = new Map<string, ExistingInstagramConvRow & { customer_external_id?: string | null; last_message_at?: string | null }>();
  const probe = {
    customer_ig_id: customerMessagingId.trim() || senderId.trim(),
    customer_external_id: senderId.trim() || null,
    customer_name: customerName,
  };

  if (tryIds.length > 0) {
    const orParts = tryIds.flatMap((id) => [
      `customer_ig_id.eq.${id}`,
      `customer_external_id.eq.${id}`,
    ]);
    const { data: directRows } = await supabase
      .from("instagram_conversations")
      .select("id, first_inbound_at, customer_name, customer_ig_id, customer_external_id, last_message_at")
      .eq("organization_id", orgId)
      .eq("instagram_business_account_id", inboxBusinessAccountId)
      .or(orParts.join(","))
      .order("last_message_at", { ascending: false })
      .limit(20);

    for (const row of directRows ?? []) {
      const r = row as ExistingInstagramConvRow & {
        customer_external_id?: string | null;
        last_message_at?: string | null;
      };
      matches.set(r.id, r);
    }
  }

  const dedupeKey = instagramConversationCustomerDedupeKey(
    customerMessagingId,
    senderId,
    customerName,
  );
  const usernameKey = normalizeInstagramUsername(
    customerName?.trim().startsWith("@") ? customerName : null,
  );

  const { data: candidates } = await supabase
    .from("instagram_conversations")
    .select("id, first_inbound_at, customer_name, customer_ig_id, customer_external_id, last_message_at")
    .eq("organization_id", orgId)
    .eq("instagram_business_account_id", inboxBusinessAccountId)
    .order("last_message_at", { ascending: false })
    .limit(80);

  for (const row of candidates ?? []) {
    const r = row as ExistingInstagramConvRow & {
      customer_external_id?: string | null;
      last_message_at?: string | null;
    };

    if (dedupeKey) {
      const rowKey = instagramConversationCustomerDedupeKey(
        r.customer_ig_id,
        r.customer_external_id ?? null,
        r.customer_name,
      );
      if (rowKey === dedupeKey) {
        matches.set(r.id, r);
        continue;
      }
    }

    if (instagramCustomerIdentitiesOverlap(probe, r)) {
      matches.set(r.id, r);
      continue;
    }

    if (usernameKey) {
      const rowUsername = normalizeInstagramUsername(
        r.customer_name?.trim().startsWith("@") ? r.customer_name : null,
      );
      if (rowUsername && rowUsername === usernameKey) {
        matches.set(r.id, r);
      }
    }
  }

  const rows = [...matches.values()];
  if (rows.length === 0) return null;
  if (rows.length === 1) return rows[0];

  console.warn("[instagram-webhook] merging duplicate IG conversations", {
    orgId,
    inboxBusinessAccountId,
    ids: rows.map((r) => r.id),
    tryIds,
    dedupeKey,
  });
  return mergeInstagramConversationDuplicates(supabase, rows);
}

/** Resolve messaging id + display name before conversation lookup (all webhook paths). */
async function resolveInstagramCustomerIdentity(
  supabase: ReturnType<typeof createClient>,
  orgId: string,
  inboxBusinessAccountId: string,
  senderId: string,
  facebookPageId: string | null | undefined,
  accessToken: string | null,
): Promise<{ customerMessagingId: string; customerName: string | null }> {
  let customerMessagingId = senderId.trim();
  if (accessToken && facebookPageId) {
    customerMessagingId = await resolveInstagramDmRecipientIdWithRetry(
      supabase,
      orgId,
      inboxBusinessAccountId,
      senderId,
      String(facebookPageId).trim(),
      accessToken,
      { altCustomerIds: [senderId], attempts: 3, delayMs: 500 },
    );
  }

  let customerName: string | null = null;
  const linkedSender = await lookupConnectedIgAccountInOrg(supabase, orgId, senderId);
  if (linkedSender?.customer_name) {
    customerName = linkedSender.customer_name;
  } else if (accessToken) {
    customerName = await fetchInstagramSenderDisplayName(senderId, accessToken);
  }

  return { customerMessagingId, customerName };
}

/** IDs that represent our inbox (Page / IG business account), not the customer. */
function collectOwnedInboxIds(
  account: InstagramWebhookAccount,
  effectiveInboxId: string,
  entryId: string | null,
): Set<string> {
  const ids = new Set<string>();
  for (const id of [
    effectiveInboxId,
    account.instagram_business_account_id,
    account.facebook_page_id,
    entryId,
  ]) {
    const trimmed = String(id ?? "").trim();
    if (trimmed) ids.add(trimmed);
  }
  return ids;
}

function isOwnedInboxParticipant(participantId: string | null, ownedIds: Set<string>): boolean {
  const p = (participantId ?? "").trim();
  return p.length > 0 && ownedIds.has(p);
}

/** True when webhook event is our API/Page outbound (not a customer DM). Matches Messenger is_echo skip. */
function isInstagramOutboundWebhookEvent(
  message: MessagingEvtLoop["message"] | undefined,
  senderId: string | null,
  ownedInboxIds: Set<string>,
): boolean {
  if (!message || message.is_deleted) return false;
  if (message.is_echo === true) return true;
  // Customer DMs have the customer as sender; our sends echo with Page/IG inbox id as sender.
  return isOwnedInboxParticipant(senderId, ownedInboxIds);
}

async function findConversationWithRecentOutboundBody(
  supabase: ReturnType<typeof createClient>,
  orgId: string,
  inboxBusinessAccountId: string,
  bodyText: string,
  withinMs = 5 * 60 * 1000,
): Promise<ExistingInstagramConvRow | null> {
  const trimmedBody = bodyText.trim();
  if (!trimmedBody) return null;
  const since = new Date(Date.now() - withinMs).toISOString();

  const { data: recentOutbound } = await supabase
    .from("instagram_messages")
    .select("conversation_id, body, created_at")
    .eq("direction", "outbound")
    .gte("created_at", since)
    .order("created_at", { ascending: false })
    .limit(15);

  for (const row of recentOutbound ?? []) {
    const msg = row as { conversation_id?: string; body?: string | null };
    if ((msg.body ?? "").trim() !== trimmedBody || !msg.conversation_id) continue;

    const { data: conv } = await supabase
      .from("instagram_conversations")
      .select("id, first_inbound_at, customer_name, customer_ig_id, customer_external_id, last_message_at")
      .eq("id", msg.conversation_id)
      .eq("organization_id", orgId)
      .eq("instagram_business_account_id", inboxBusinessAccountId)
      .maybeSingle();

    if (conv?.id) {
      console.warn("[instagram-webhook] matched recent outbound body — avoid duplicate inbound thread", {
        conversation_id: conv.id,
        body: trimmedBody.slice(0, 80),
      });
      return conv as ExistingInstagramConvRow;
    }
  }
  return null;
}

async function skipIfOutboundInstagramMessageAlreadyStored(
  supabase: ReturnType<typeof createClient>,
  mid: string | null,
  meta: Record<string, unknown>,
): Promise<boolean> {
  if (!mid) return false;
  const { data: existingMsg } = await supabase
    .from("instagram_messages")
    .select("id, direction")
    .eq("platform_message_id", mid)
    .maybeSingle();
  if (existingMsg?.id) {
    console.log("[instagram-webhook] skip duplicate platform_message_id", { ...meta, mid, direction: existingMsg.direction });
    return true;
  }
  return false;
}

async function lookupConnectedIgAccountInOrg(
  supabase: ReturnType<typeof createClient>,
  organizationId: string,
  igScopedId: string,
): Promise<{ customer_ig_id: string; customer_name: string | null } | null> {
  const sid = igScopedId.trim();
  if (!sid) return null;
  const { data: rows } = await supabase
    .from("organization_instagram_accounts")
    .select("instagram_business_account_id, instagram_username, instagram_name")
    .eq("organization_id", organizationId)
    .eq("is_active", true);
  for (const row of rows ?? []) {
    const r = row as {
      instagram_business_account_id: string;
      instagram_username: string | null;
      instagram_name: string | null;
    };
    if (String(r.instagram_business_account_id).trim() === sid) {
      const uname = r.instagram_username?.trim();
      return {
        customer_ig_id: sid,
        customer_name: uname ? `@${uname}` : (r.instagram_name?.trim() || null),
      };
    }
  }
  return null;
}

function extractMessagingFromEntry(entry: Record<string, unknown>): MessagingEvt[] {
  const events: MessagingEvt[] = [];
  const messaging = entry.messaging;
  if (Array.isArray(messaging) && messaging.length > 0) {
    events.push(...(messaging as MessagingEvt[]));
  }

  const changes = entry.changes;
  if (!Array.isArray(changes)) return events;

  for (const ch of changes) {
    const change = ch as Record<string, unknown>;
    const field = typeof change.field === "string" ? change.field : "";
    const val = change.value as Record<string, unknown> | undefined;
    if (!val) continue;

    if (field === "messages" || field === "messaging") {
      if (Array.isArray(val.messaging)) {
        events.push(...(val.messaging as MessagingEvt[]));
        continue;
      }
      const nested = val.messaging_event as MessagingEvt | undefined;
      if (nested?.sender?.id != null && nested.message) {
        events.push(nested);
        continue;
      }
      if (val.sender && val.message) {
        events.push(val as MessagingEvt);
      }
    }
  }

  return events;
}

type InstagramCommentWebhookEvent = {
  commentId: string;
  mediaId: string;
  authorIgScopedId: string | null;
  authorUsername: string | null;
  commentText: string;
  parentCommentId: string | null;
  verb: string | null;
};

function extractInstagramCommentChangesFromEntry(
  entry: Record<string, unknown>,
): InstagramCommentWebhookEvent[] {
  const events: InstagramCommentWebhookEvent[] = [];
  const changes = entry.changes;
  if (!Array.isArray(changes)) return events;

  for (const ch of changes) {
    const change = ch as Record<string, unknown>;
    const field = typeof change.field === "string" ? change.field : "";
    if (field !== "comments") continue;

    const val = change.value as Record<string, unknown> | undefined;
    if (!val) continue;

    const commentId = typeof val.id === "string" ? val.id.trim() : String(val.id ?? "").trim();
    const media = val.media as Record<string, unknown> | undefined;
    const mediaId = typeof media?.id === "string" ? media.id.trim() : String(media?.id ?? "").trim();
    const from = val.from as Record<string, unknown> | undefined;
    const authorRaw = from?.id != null ? String(from.id).trim() : "";
    const authorIgScopedId = authorRaw || null;
    const authorUsername = typeof from?.username === "string"
      ? from.username.trim()
      : typeof from?.name === "string"
      ? from.name.trim()
      : null;
    const commentText = typeof val.text === "string" ? val.text.trim() : "";
    const parentRaw = val.parent_id != null ? String(val.parent_id).trim() : "";
    const parentCommentId = parentRaw || null;
    const verb = typeof val.verb === "string" ? val.verb.trim().toLowerCase() : null;

    if (!commentId || !mediaId) continue;

    events.push({ commentId, mediaId, authorIgScopedId, authorUsername, commentText, parentCommentId, verb });
  }

  return events;
}

async function processInstagramCommentWebhookEvents(
  supabase: ReturnType<typeof createClient>,
  webhookObject: string,
  entryId: string | null,
  events: InstagramCommentWebhookEvent[],
): Promise<number> {
  if (events.length === 0) return 0;

  if (webhookObject === "page") {
    return 0;
  }
  if (webhookObject !== "instagram") return 0;

  const account = await resolveInstagramAccountForMessaging(supabase, entryId, null, null);
  if (!account) {
    console.error(
      "[instagram-webhook] comment webhook: account not found for entry:",
      entryId ?? "(missing)",
    );
    return 0;
  }

  const businessIgId = String(account.instagram_business_account_id).trim();
  const orgId = account.organization_id;
  const accessToken = (account.page_access_token ?? "").trim();
  const pageId = String(account.facebook_page_id ?? "").trim();
  let processed = 0;

  for (const evt of events) {
    if (evt.verb === "remove") {
      let deleteQuery = supabase
        .from("meta_manage_comments_inbound_comments")
        .delete()
        .eq("organization_id", orgId)
        .eq("platform", "instagram")
        .eq("account_id", businessIgId)
        .eq("comment_id", evt.commentId);
      if (evt.mediaId) {
        deleteQuery = deleteQuery.eq("media_id", evt.mediaId);
      }
      const { error } = await deleteQuery;
      if (error) {
        console.warn("[instagram-webhook] comment remove delete error", evt.commentId, error.message);
      } else {
        processed += 1;
      }
      continue;
    }

    if (evt.authorIgScopedId && evt.authorIgScopedId === businessIgId) {
      console.log("[instagram-webhook] skip self-comment", evt.commentId);
      continue;
    }

    try {
      await syncMetaManageCommentsInboundComments(
        supabase,
        orgId,
        "instagram",
        businessIgId,
        evt.mediaId,
        [evt.commentId],
      );
      console.log("[instagram-webhook] comments webhook received", {
        orgId,
        mediaId: evt.mediaId,
        commentId: evt.commentId,
        authorIgScopedId: evt.authorIgScopedId,
        parentCommentId: evt.parentCommentId,
      });
      processed += 1;

      if (accessToken && pageId && evt.authorIgScopedId) {
        scheduleLeadMagnetCommentTrigger({
          platform: "instagram",
          organizationId: orgId,
          accountId: businessIgId,
          mediaId: evt.mediaId,
          commentId: evt.commentId,
          authorScopedId: evt.authorIgScopedId,
          authorUsername: evt.authorUsername,
          commentText: evt.commentText,
          accessToken,
          pageId,
        });
      }
    } catch (e) {
      console.error("[instagram-webhook] syncMetaManageCommentsInboundComments error", e);
    }
  }

  return processed;
}

async function processFacebookFeedCommentEvents(
  supabase: ReturnType<typeof createClient>,
  entryId: string | null,
  events: ReturnType<typeof extractFacebookFeedCommentChangesFromEntry>,
): Promise<number> {
  if (events.length === 0 || !entryId) return 0;

  let orgId: string | null = null;
  let pageId = "";
  let accessToken = "";

  const { data: fbPage } = await supabase
    .from("organization_facebook_pages")
    .select("organization_id, facebook_page_id, page_access_token")
    .eq("facebook_page_id", entryId)
    .eq("is_active", true)
    .maybeSingle();

  if (fbPage?.organization_id && fbPage.facebook_page_id) {
    orgId = String(fbPage.organization_id);
    pageId = String(fbPage.facebook_page_id).trim();
    accessToken = String(fbPage.page_access_token ?? "").trim();
  } else {
    const { data: igLinked } = await supabase
      .from("organization_instagram_accounts")
      .select("organization_id, facebook_page_id, page_access_token")
      .eq("facebook_page_id", entryId)
      .eq("is_active", true)
      .maybeSingle();

    if (igLinked?.organization_id && igLinked.facebook_page_id) {
      orgId = String(igLinked.organization_id);
      pageId = String(igLinked.facebook_page_id).trim();
      accessToken = String(igLinked.page_access_token ?? "").trim();
      console.log("[instagram-webhook] FB feed comment: matched page via linked IG account", entryId);
    }
  }

  if (!orgId || !pageId) {
    console.log("[instagram-webhook] FB feed comment: page not found", entryId);
    return 0;
  }

  let processed = 0;

  for (const evt of events) {
    if (evt.verb === "remove") continue;
    if (!evt.authorScopedId || !accessToken) continue;

    if (evt.authorScopedId === pageId) {
      console.log("[instagram-webhook] skip FB self-comment", evt.commentId);
      continue;
    }

    try {
      await syncMetaManageCommentsInboundComments(
        supabase,
        orgId,
        "facebook",
        pageId,
        evt.postId,
        [evt.commentId],
      );
      processed += 1;

      scheduleLeadMagnetCommentTrigger({
        platform: "facebook",
        organizationId: orgId,
        accountId: pageId,
        mediaId: evt.postId,
        commentId: evt.commentId,
        authorScopedId: evt.authorScopedId,
        authorUsername: evt.authorUsername,
        commentText: evt.commentText,
        accessToken,
        pageId,
      });
    } catch (e) {
      console.error("[instagram-webhook] FB feed comment sync error", e);
    }
  }

  return processed;
}

function livechatPushUsesDatabaseWebhookOnly(): boolean {
  return Deno.env.get("LIVECHAT_USE_DATABASE_WEBHOOK_FOR_PUSH") === "true";
}

async function notifyLivechatInboundPush(
  table: LivechatPushTable,
  record: Record<string, unknown>,
): Promise<void> {
  if (livechatPushUsesDatabaseWebhookOnly()) return;

  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  if (!supabaseUrl || !serviceRoleKey) {
    console.warn("notifyLivechatInboundPush: missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY");
    return;
  }

  const url = `${supabaseUrl.replace(/\/$/, "")}/functions/v1/livechat-send-push`;
  try {
    const res = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${serviceRoleKey}`,
        apikey: serviceRoleKey,
      },
      body: JSON.stringify({
        type: "INSERT",
        table,
        schema: "public",
        record,
      }),
    });
    if (!res.ok) {
      const t = await res.text();
      console.error("notifyLivechatInboundPush: livechat-send-push HTTP error", res.status, t.slice(0, 800));
    }
  } catch (e) {
    console.error("notifyLivechatInboundPush: fetch failed", e);
  }
}

Deno.serve(async (req: Request) => {
  const url = new URL(req.url);
  console.log("[instagram-webhook] ENTRY", req.method, url.pathname);

  if (req.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: corsHeaders });
  }

  try {
    const supabase = createClient(
      Deno.env.get("SUPABASE_URL") ?? "",
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
    );

    if (req.method === "GET") {
      const mode = url.searchParams.get("hub.mode");
      const token = url.searchParams.get("hub.verify_token");
      const challenge = url.searchParams.get("hub.challenge");

      if (mode !== "subscribe" || !challenge) {
        return new Response("instagram-webhook ok", { status: 200, headers: { ...corsHeaders, "Content-Type": "text/plain" } });
      }

      let verified = false;
      if (token) {
        const { data: igAccount } = await supabase
          .from("organization_instagram_accounts")
          .select("id")
          .eq("verify_token", token)
          .eq("is_active", true)
          .maybeSingle();
        if (igAccount) verified = true;
        if (!verified) {
          const { data: metaByVerify } = await supabase
            .from("organization_meta_config")
            .select("id")
            .eq("verify_token", token)
            .eq("is_active", true)
            .maybeSingle();
          if (metaByVerify) verified = true;
        }
        if (!verified) {
          const { data: metaByIgToken } = await supabase
            .from("organization_meta_config")
            .select("id")
            .eq("instagram_verify_token", token)
            .eq("is_active", true)
            .maybeSingle();
          if (metaByIgToken) verified = true;
        }
        if (!verified) {
          const { data: fbPage } = await supabase
            .from("organization_facebook_pages")
            .select("id")
            .eq("verify_token", token)
            .eq("is_active", true)
            .maybeSingle();
          if (fbPage) verified = true;
        }
      }

      if (!verified) {
        console.error("[instagram-webhook] GET: verify_token not found");
        return new Response("Forbidden", { status: 403, headers: corsHeaders });
      }
      console.log("[instagram-webhook] GET: verification success");
      const challengeStr = challenge != null ? String(challenge) : "";
      return new Response(challengeStr, { status: 200, headers: { ...corsHeaders, "Content-Type": "text/plain" } });
    }

    if (req.method !== "POST") {
      return new Response(JSON.stringify({ error: "Method not allowed" }), {
        status: 405,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const body = await req.json().catch((e) => {
      console.error("[instagram-webhook] POST body parse error", e);
      return {};
    });
    const bodyObject = body?.object ?? "(missing)";
    const entryCount = Array.isArray(body?.entry) ? body.entry.length : 0;
    console.log("[instagram-webhook] POST received — object:", bodyObject, "entries:", entryCount);
    const webhookObject = String(body?.object ?? "").trim();
    if (!SUPPORTED_INSTAGRAM_WEBHOOK_OBJECTS.has(webhookObject)) {
      console.log(
        "[instagram-webhook] POST: unsupported object, ignoring. Payload object:",
        bodyObject,
        "(expected instagram or page)",
      );
      return new Response(JSON.stringify({ success: true, ignored: true, reason: "unsupported_object" }), {
        status: 200,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const entries = body?.entry ?? [];
    if (entries.length > 0) {
      const first = entries[0] as Record<string, unknown>;
      const keys = first ? Object.keys(first) : [];
      const hasChanges = Array.isArray(first?.changes) && (first.changes as unknown[]).length > 0;
      const hasMessaging = Array.isArray(first?.messaging) && (first.messaging as unknown[]).length > 0;
      console.log("[instagram-webhook] first entry keys:", keys.join(", "), "id:", first?.id, "messaging?:", hasMessaging ? (first.messaging as unknown[]).length : "none", "changes?:", hasChanges ? (first.changes as unknown[]).length : "none");
      if (hasChanges && !hasMessaging) {
        const firstChanges = (first?.changes as Array<Record<string, unknown>>) ?? [];
        const changeFields = firstChanges
          .map((c) => (typeof c.field === "string" ? c.field : ""))
          .filter(Boolean);
        if (changeFields.includes("comments")) {
          console.log("[instagram-webhook] Payload has comments changes — comment ingest path.");
        } else {
          console.log(
            "[instagram-webhook] Payload has changes but no messaging/DM events. fields:",
            changeFields.join(", ") || "(none)",
          );
        }
      }
    }
    const ensuredLivechatStatusOrgs = new Set<string>();
    let processedCount = 0;
    let commentProcessedCount = 0;
    for (const entry of entries) {
      const entryRecord = entry as Record<string, unknown>;
      const entryId = entry?.id != null && entry?.id !== "" ? String(entry.id).trim() : null;

      const commentEvents = extractInstagramCommentChangesFromEntry(entryRecord);
      if (commentEvents.length > 0) {
        commentProcessedCount += await processInstagramCommentWebhookEvents(
          supabase,
          webhookObject,
          entryId,
          commentEvents,
        );
      }

      if (webhookObject === "page") {
        const fbFeedEvents = extractFacebookFeedCommentChangesFromEntry(entryRecord);
        if (fbFeedEvents.length > 0) {
          commentProcessedCount += await processFacebookFeedCommentEvents(
            supabase,
            entryId,
            fbFeedEvents,
          );
        }
      }

      const messaging = extractMessagingFromEntry(entryRecord);
      if (messaging.length === 0) continue;

      console.log(
        "[instagram-webhook] entry id:",
        entryId ?? "(missing)",
        "object:",
        webhookObject,
        "messaging events:",
        messaging.length,
      );

      if (webhookObject === "page") {
        const fbPage = await resolveFacebookPageForWebhookEntry(supabase, entryId, messaging);
        if (!fbPage) {
          const recipientHint = messaging[0]?.recipient?.id != null ? String(messaging[0].recipient.id) : "(none)";
          console.error(
            "[instagram-webhook] Facebook Page not found for entry id:",
            entryId ?? "(missing)",
            "recipient:",
            recipientHint,
            "— connect Page di /omnichannel/integrations/facebook. Meta Test pakai ID dummy; kirim pesan nyata ke Page Octa Vialdi (937482819452507).",
          );
          continue;
        }
        console.log("[instagram-webhook] Facebook Page found — page id:", fbPage.facebook_page_id, "org:", fbPage.organization_id);
        const fbProcessed = await processFacebookMessengerEvents(
          supabase,
          fbPage,
          messaging,
          async (record) => notifyLivechatInboundPush("facebook_messages", record),
          ensuredLivechatStatusOrgs,
        );
        processedCount += fbProcessed;
        continue;
      }

      type MessagingEvtLoop = MessagingEvt;
      for (const evt of messaging) {
        const e = evt as MessagingEvtLoop;

        const recipientId = e.recipient?.id != null ? String(e.recipient.id).trim() : null;
        const senderId = e.sender?.id != null ? String(e.sender.id) : null;
        let account = await resolveInstagramAccountForMessaging(supabase, entryId, recipientId, senderId);
        if (!account) {
          console.error(
            "[instagram-webhook] config not found for entry/recipient/sender:",
            { entryId, recipientId, senderId },
            "— pastikan akun Instagram di-connect di halaman Connect Instagram.",
          );
          continue;
        }

        let effectiveId = String(account.instagram_business_account_id).trim();
        let orgId = account.organization_id;
        if (!ensuredLivechatStatusOrgs.has(orgId)) {
          const { error: ensureStatusErr } = await supabase.rpc("ensure_livechat_lead_statuses_for_org", {
            p_organization_id: orgId,
          });
          if (ensureStatusErr) {
            console.warn("[instagram-webhook] ensure_livechat_lead_statuses_for_org:", ensureStatusErr.message);
          } else {
            ensuredLivechatStatusOrgs.add(orgId);
          }
        }
        let accessToken = (account.page_access_token ?? "").trim() || null;
        const ts = e.timestamp != null ? new Date(Number(e.timestamp)).toISOString() : new Date().toISOString();

        // Read / seen receipts (message_reads + messaging_seen subscriptions)
        if ((e.read || e.seen) && !e.message && !e.postback) {
          const customerIgId = senderId;
          if (!customerIgId) continue;
          const readPayload = (e.read ?? e.seen) as { watermark?: unknown; mid?: unknown };
          const { customerMessagingId, customerName } = await resolveInstagramCustomerIdentity(
            supabase,
            orgId,
            effectiveId,
            customerIgId,
            account.facebook_page_id,
            accessToken,
          );
          const convForRead = await findExistingInstagramConversation(
            supabase,
            orgId,
            effectiveId,
            customerMessagingId,
            customerIgId,
            customerName,
          );
          if (convForRead?.id) {
            await handleInstagramReadReceipt(supabase, convForRead.id, readPayload);
            processedCount += 1;
          }
          continue;
        }

        // Postback events
        if (e.postback && !e.message) {
          const postback = e.postback;
          if (!senderId) continue;
          const payload = typeof postback.payload === "string" ? postback.payload.trim() : "";
          const title = typeof postback.title === "string" ? postback.title.trim() : "";
          const bodyText = payload || title || "[Postback]";
          const mid = `postback_${senderId}_${String(e.timestamp ?? Date.now())}`;

          const { customerMessagingId, customerName } = await resolveInstagramCustomerIdentity(
            supabase,
            orgId,
            effectiveId,
            senderId,
            account.facebook_page_id,
            accessToken,
          );
          const existingConvPb = await findExistingInstagramConversation(
            supabase,
            orgId,
            effectiveId,
            customerMessagingId,
            senderId,
            customerName,
          );

          let convPbId = existingConvPb?.id ?? null;
          if (!convPbId) {
            const newConvId = crypto.randomUUID();
            const ticketId = "IG-" + newConvId.replace(/-/g, "").slice(0, 8).toUpperCase();
            const orgOrGlobalPb = `organization_id.eq.${orgId},organization_id.is.null`;
            const { data: openSt } = await supabase.from("lead_statuses").select("id").or(orgOrGlobalPb).eq("name", "Open").maybeSingle();
            const { data: unreadSt } = openSt?.id
              ? { data: null }
              : await supabase.from("lead_statuses").select("id").or(orgOrGlobalPb).eq("name", "Unread").maybeSingle();
            const { data: insertedPb, error: insertPbErr } = await supabase
              .from("instagram_conversations")
              .insert({
                id: newConvId,
                organization_id: orgId,
                instagram_business_account_id: effectiveId,
                customer_ig_id: customerMessagingId,
                customer_external_id: senderId,
                ...(customerName ? { customer_name: customerName } : {}),
                ticket_id: ticketId,
                lead_status_id: openSt?.id ?? unreadSt?.id ?? null,
                last_message_at: ts,
                last_message_body: bodyText.slice(0, 200),
                last_message_direction: "inbound",
                last_inbound_at: ts,
                first_inbound_at: ts,
                updated_at: ts,
              })
              .select("id")
              .single();
            if (insertPbErr) {
              const retried = await findExistingInstagramConversation(
                supabase,
                orgId,
                effectiveId,
                customerMessagingId,
                senderId,
                customerName,
              );
              convPbId = retried?.id ?? null;
            } else {
              convPbId = insertedPb?.id ?? null;
            }
          }

          if (convPbId) {
            await extendInstagramMetaSession(supabase, convPbId, ts);
            await supabase
              .from("instagram_conversations")
              .update({
                last_message_at: ts,
                last_message_body: bodyText.slice(0, 200),
                last_message_direction: "inbound",
                last_inbound_at: ts,
                updated_at: ts,
              })
              .eq("id", convPbId);
            const pbPayload = {
              conversation_id: convPbId,
              direction: "inbound",
              platform_message_id: mid,
              body: bodyText,
              message_type: "postback",
              raw_metadata: evt,
              created_at: ts,
            };
            await supabase.from("instagram_messages").insert(pbPayload);
            await notifyLivechatInboundPush("instagram_messages", pbPayload);
            processedCount += 1;

            if (payload.startsWith(LEAD_MAGNET_PAYLOAD_PREFIX) && accessToken && convPbId) {
              scheduleLeadMagnetPostbackTrigger({
                platform: "instagram",
                organizationId: orgId,
                accountId: effectiveId,
                participantScopedId: senderId,
                participantUsername: customerName,
                payload,
                conversationId: convPbId,
                accessToken,
                pageId: String(account.facebook_page_id ?? "").trim(),
              });
            }
          }
          continue;
        }

        if (e.message?.is_echo) {
          const echoRecipientInbox = recipientId
            ? await resolveEchoBridgeInboxAccount(supabase, account, recipientId)
            : null;
          if (!echoRecipientInbox) {
            console.log("[instagram-webhook] skip: is_echo (outbound to external customer)", {
              senderId,
              recipientId,
              inbox: account.instagram_username,
            });
            continue;
          }
          console.log("[instagram-webhook] bridge is_echo to connected inbox", {
            from: account.instagram_username,
            to: echoRecipientInbox.instagram_username,
            recipientId,
            senderId,
          });
          account = echoRecipientInbox;
          effectiveId = String(echoRecipientInbox.instagram_business_account_id).trim();
          orgId = echoRecipientInbox.organization_id;
          accessToken = (echoRecipientInbox.page_access_token ?? "").trim() || null;
          if (!ensuredLivechatStatusOrgs.has(orgId)) {
            const { error: ensureStatusErr } = await supabase.rpc("ensure_livechat_lead_statuses_for_org", {
              p_organization_id: orgId,
            });
            if (ensureStatusErr) {
              console.warn("[instagram-webhook] ensure_livechat_lead_statuses_for_org:", ensureStatusErr.message);
            } else {
              ensuredLivechatStatusOrgs.add(orgId);
            }
          }
        }

        const mid = e.message?.mid != null ? String(e.message.mid) : null;

        const ownedInboxIds = collectOwnedInboxIds(account, effectiveId, entryId);
        if (
          e.message &&
          !e.message.is_deleted &&
          isInstagramOutboundWebhookEvent(e.message, senderId, ownedInboxIds)
        ) {
          if (await skipIfOutboundInstagramMessageAlreadyStored(supabase, mid, {
            reason: "outbound_or_echo",
            senderId,
            recipientId,
            is_echo: e.message.is_echo === true,
            owned_inbox_ids: [...ownedInboxIds],
          })) {
            processedCount += 1;
          } else {
            console.log("[instagram-webhook] skip outbound/echo (sender is inbox/page)", {
              senderId,
              recipientId,
              mid,
              is_echo: e.message.is_echo === true,
            });
          }
          continue;
        }

        // Deleted message: update existing row
        if (e.message?.is_deleted && mid && senderId) {
          const { customerMessagingId, customerName } = await resolveInstagramCustomerIdentity(
            supabase,
            orgId,
            effectiveId,
            senderId,
            account.facebook_page_id,
            accessToken,
          );
          const convDel = await findExistingInstagramConversation(
            supabase,
            orgId,
            effectiveId,
            customerMessagingId,
            senderId,
            customerName,
          );
          if (convDel?.id) {
            await supabase
              .from("instagram_messages")
              .update({ body: "[Deleted]", message_type: "text" })
              .eq("conversation_id", convDel.id)
              .eq("platform_message_id", mid);
            processedCount += 1;
          }
          continue;
        }

        if (!senderId) {
          console.log("[instagram-webhook] skip: no senderId");
          continue;
        }

        const { body: bodyText, messageType } = getMessageBody(evt as Record<string, unknown>);
        const lastBody = bodyText.slice(0, 200);

        // Reject misrouted webhooks where Meta sends our Page id as sender (would become "Instagram Contact").
        if (isOwnedInboxParticipant(senderId, ownedInboxIds)) {
          console.log("[instagram-webhook] skip: sender is owned inbox/page id on message path", { senderId, mid });
          continue;
        }

        if (recipientId && recipientId !== effectiveId) {
          console.warn("[instagram-webhook] recipientId differs from resolved inbox account", {
            recipientId,
            effectiveId,
            inbox: account.instagram_username,
          });
        }

        const { customerMessagingId, customerName: resolvedCustomerName } = await resolveInstagramCustomerIdentity(
          supabase,
          orgId,
          effectiveId,
          senderId!,
          account.facebook_page_id,
          accessToken,
        );
        let customerName = resolvedCustomerName;

        let existingConvResolved = await findExistingInstagramConversation(
          supabase,
          orgId,
          effectiveId,
          customerMessagingId,
          senderId!,
          customerName,
        );

        const outboundEchoConv = await findConversationWithRecentOutboundBody(
          supabase,
          orgId,
          effectiveId,
          bodyText,
        );
        if (outboundEchoConv && !existingConvResolved) {
          if (await skipIfOutboundInstagramMessageAlreadyStored(supabase, mid, {
            reason: "body_matches_recent_outbound_no_customer_conv",
            conversation_id: outboundEchoConv.id,
          })) {
            processedCount += 1;
          } else {
            console.log("[instagram-webhook] skip misrouted echo (matches recent outbound, no customer thread)", {
              conversation_id: outboundEchoConv.id,
              body: bodyText.slice(0, 80),
              senderId,
              mid,
            });
          }
          continue;
        }

        const existingName = existingConvResolved?.customer_name?.trim() ?? "";
        if (!customerName && existingName) {
          customerName = existingName;
        }

        const convPayload = {
          organization_id: orgId,
          instagram_business_account_id: effectiveId,
          customer_ig_id: customerMessagingId,
          customer_external_id: senderId,
          ...(customerName ? { customer_name: customerName } : {}),
          last_message_at: ts,
          last_message_body: lastBody,
          last_message_direction: "inbound",
          last_message_status: null as string | null,
          first_inbound_at: null as string | null,
          last_inbound_at: ts,
          updated_at: ts,
        };

        let conv: { id: string; first_inbound_at: string | null } | null = null;
        if (existingConvResolved) {
          const { data: updated } = await supabase
            .from("instagram_conversations")
            .update({
              last_message_at: ts,
              last_message_body: lastBody,
              last_message_direction: "inbound",
              last_inbound_at: ts,
              updated_at: ts,
              customer_ig_id: customerMessagingId,
              customer_external_id: senderId,
              ...(customerName && !existingName ? { customer_name: customerName } : {}),
            })
            .eq("id", existingConvResolved.id)
            .select("id, first_inbound_at")
            .single();
          conv = updated;
        } else {
          const newConvId = crypto.randomUUID();
          const ticketId = "IG-" + newConvId.replace(/-/g, "").slice(0, 8).toUpperCase();
          const orgOrGlobalNew = `organization_id.eq.${orgId},organization_id.is.null`;
          const { data: openStatus } = await supabase
            .from("lead_statuses")
            .select("id")
            .or(orgOrGlobalNew)
            .eq("name", "Open")
            .maybeSingle();
          const { data: unreadStatus } = openStatus?.id
            ? { data: null }
            : await supabase
                .from("lead_statuses")
                .select("id")
                .or(orgOrGlobalNew)
                .eq("name", "Unread")
                .maybeSingle();
          const leadStatusId = openStatus?.id ?? unreadStatus?.id ?? null;
          if (!leadStatusId) {
            console.warn(
              "[instagram-webhook] new conv: no Open/Unread lead_status (org or global); conversation may insert with null lead_status_id",
              { organization_id: orgId },
            );
          }

          const { data: inserted, error: insertErr } = await supabase
            .from("instagram_conversations")
            .insert({
              id: newConvId,
              ...convPayload,
              ticket_id: ticketId,
              lead_status_id: leadStatusId,
              first_inbound_at: ts,
            })
            .select("id, first_inbound_at")
            .single();
          if (insertErr) {
            console.warn("[instagram-webhook] conversation insert error, retry lookup", insertErr);
            const retried = await findExistingInstagramConversation(
              supabase,
              orgId,
              effectiveId,
              customerMessagingId,
              senderId!,
              customerName,
            );
            if (retried) {
              const { data: updatedAfterRace } = await supabase
                .from("instagram_conversations")
                .update({
                  last_message_at: ts,
                  last_message_body: lastBody,
                  last_message_direction: "inbound",
                  last_inbound_at: ts,
                  updated_at: ts,
                  customer_ig_id: customerMessagingId,
                  customer_external_id: senderId,
                  ...(customerName && !existingName ? { customer_name: customerName } : {}),
                })
                .eq("id", retried.id)
                .select("id, first_inbound_at")
                .single();
              conv = updatedAfterRace;
            } else {
              continue;
            }
          } else {
            conv = inserted;
            const createdByDisplayName = account.instagram_username?.trim()
              ? `@${account.instagram_username.trim()}`
              : (account.instagram_name?.trim() || "Instagram");
            await ensureLeadForNewInstagramConversation(
              supabase,
              orgId,
              conv!.id,
              customerName || "Instagram contact",
              lastBody || "Instagram",
              senderId,
              createdByDisplayName
            );
            const { error: newCycleErr } = await supabase.from("instagram_conversation_cycles").insert({
              conversation_id: conv!.id,
              cycle_started_at: ts,
            });
            if (newCycleErr) console.error("[instagram-webhook] new conversation cycle insert error", newCycleErr);
          }
        }

        if (!conv || !mid) {
          console.log("[instagram-webhook] skip save: no conv or mid", { conv: !!conv, mid: !!mid });
          continue;
        }

        if (await skipIfOutboundInstagramMessageAlreadyStored(supabase, mid, {
          reason: "duplicate_before_inbound_insert",
          conversation_id: conv.id,
        })) {
          processedCount += 1;
          continue;
        }

        await extendInstagramMetaSession(supabase, conv.id, ts);

        let mediaUrl: string | null = null;
        const msgRecord = (evt as Record<string, unknown>).message as Record<string, unknown> | undefined;
        const attachmentInfo = msgRecord ? getInstagramAttachmentInfo(msgRecord) : null;
        if (attachmentInfo && accessToken) {
          const eagerTypes = new Set(["image", "video"]);
          if (eagerTypes.has(attachmentInfo.type)) {
            mediaUrl = await downloadInstagramAttachmentToStorage(
              attachmentInfo.url,
              accessToken,
              supabase,
              conv.id,
              mid,
              attachmentInfo.type,
            );
          }
        }

        const insertPayload: Record<string, unknown> = {
          conversation_id: conv.id,
          direction: "inbound",
          platform_message_id: mid,
          body: bodyText,
          message_type: messageType,
          raw_metadata: evt,
          created_at: ts,
        };
        if (mediaUrl) insertPayload.media_url = mediaUrl;

        // Inbound reply context: extract reply_to.mid so UI can show reply preview
        const msgObj = (evt as Record<string, unknown>).message as { reply_to?: { mid?: string } } | undefined;
        const replyToMid = msgObj?.reply_to?.mid != null ? String(msgObj.reply_to.mid).trim() : null;
        if (replyToMid) {
          insertPayload.reply_to_platform_message_id = replyToMid;
          const { data: repliedToRow } = await supabase
            .from("instagram_messages")
            .select("body, message_type")
            .eq("conversation_id", conv.id)
            .eq("platform_message_id", replyToMid)
            .maybeSingle();
          if (repliedToRow) {
            const repliedBody = repliedToRow.body;
            const repliedType = (repliedToRow.message_type ?? "text") as string;
            insertPayload.reply_to_body =
              repliedBody != null && repliedBody !== ""
                ? String(repliedBody).slice(0, 500)
                : ["image", "video", "file"].includes((repliedType || "").toLowerCase())
                  ? `[${repliedType}]`
                  : "[Pesan]";
            insertPayload.reply_to_message_type = repliedType;
          } else {
            insertPayload.reply_to_body = "[Pesan]";
          }
        }

        const { error: msgErr } = await supabase.from("instagram_messages").insert(insertPayload);
        if (msgErr) {
          console.error("[instagram-webhook] instagram_messages insert error", msgErr);
          continue;
        }
        await notifyLivechatInboundPush("instagram_messages", insertPayload);

        if (!existingConvResolved?.first_inbound_at && conv.first_inbound_at) {
          await supabase
            .from("instagram_conversations")
            .update({ first_inbound_at: ts, updated_at: ts })
            .eq("id", conv.id);
        }

        // Resolve-cycle: when existing conversation receives inbound, re-open to Open (Unread) if status is Closed/Resolve or null (same logic as whatsapp-webhook)
        if (existingConvResolved) {
          const { data: convRow } = await supabase
            .from("instagram_conversations")
            .select("lead_status_id")
            .eq("id", conv.id)
            .single();
          const statusId = convRow?.lead_status_id ?? null;
          let leadStatusName: string | null = null;
          if (statusId) {
            const { data: statusRow } = await supabase
              .from("lead_statuses")
              .select("name")
              .eq("id", statusId)
              .maybeSingle();
            leadStatusName = (statusRow?.name as string) ?? null;
          }
          // Prefer "Open", fallback "Unread". Include global statuses (organization_id IS NULL) for all tenants.
          const orgOrGlobal = `organization_id.eq.${orgId},organization_id.is.null`;
          const { data: openStatus } = await supabase
            .from("lead_statuses")
            .select("id")
            .or(orgOrGlobal)
            .eq("name", "Open")
            .maybeSingle();
          const { data: unreadStatus } = openStatus?.id
            ? { data: null }
            : await supabase.from("lead_statuses").select("id").or(orgOrGlobal).eq("name", "Unread").maybeSingle();
          const openStatusId = openStatus?.id ?? unreadStatus?.id ?? null;
          const statusNameLower = leadStatusName?.trim().toLowerCase() ?? "";
          const isResolved = statusNameLower === "closed" || statusNameLower === "resolve";
          const isExpired = statusNameLower === "expired";
          const isNewOrReopen = openStatusId && (statusId == null || isResolved || isExpired);
          if (isNewOrReopen) {
            const { data: convBefore } = await supabase
              .from("instagram_conversations")
              .select("organization_id, ticket_id")
              .eq("id", conv.id)
              .maybeSingle();
            const { error: updateErr } = await supabase
              .from("instagram_conversations")
              .update({ lead_status_id: openStatusId, last_inbound_at: ts, updated_at: ts })
              .eq("id", conv.id);
            if (updateErr) {
              console.error("[instagram-webhook] Reopen to Open (Unread) update error:", updateErr);
            } else {
              console.log("[instagram-webhook] Reopened conversation to Open (Unread):", conv.id, { openStatusId, hadStatus: statusId });
            }
            if (convBefore?.organization_id && openStatusId) {
              const ticketId =
                (convBefore.ticket_id as string) ?? `IG-${conv.id.replace(/-/g, "").slice(0, 8).toUpperCase()}`;
              const { error: leadErr } = await supabase
                .from("leads")
                .update({ status_id: openStatusId, updated_at: ts })
                .eq("organization_id", convBefore.organization_id)
                .eq("ticket_id", ticketId);
              if (leadErr) console.error("[instagram-webhook] Reopen: sync leads.status_id to Open failed:", leadErr);
            }
            const { error: cycleErr } = await supabase.from("instagram_conversation_cycles").insert({
              conversation_id: conv.id,
              cycle_started_at: ts,
            });
            if (cycleErr) console.error("[instagram-webhook] New cycle insert error:", cycleErr);
          }
        }

        console.log("[instagram-webhook] message saved", { convId: conv.id, mid });
        processedCount += 1;
      }
    }

    return new Response(
      JSON.stringify({ success: true, processed: processedCount, commentProcessedCount }),
      {
        status: 200,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      },
    );
  } catch (err) {
    console.error("[instagram-webhook] error", err);
    return new Response(JSON.stringify({ error: "Webhook failed" }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { LEAD_MAGNET_PAYLOAD_PREFIX } from "./leadMagnet/types.ts";
import { scheduleLeadMagnetPostbackTrigger } from "./leadMagnet/webhookBridge.ts";

const META_GRAPH_VERSION = "v21.0";
const MEDIA_BUCKET = "whatsapp-media";
const META_SESSION_MS = 24 * 60 * 60 * 1000;
const LAZY_VIDEO_BYTES = 10 * 1024 * 1024;

export type FacebookWebhookPage = {
  organization_id: string;
  facebook_page_id: string;
  page_name: string | null;
  page_access_token: string | null;
};

export type MessagingEvt = {
  message?: {
    is_echo?: boolean;
    is_deleted?: boolean;
    is_unsupported?: boolean;
    mid?: string;
    text?: unknown;
    attachments?: unknown[];
    reply_to?: { mid?: string };
    quick_reply?: { payload?: string };
  };
  postback?: { title?: string; payload?: string };
  read?: { watermark?: unknown; mid?: unknown };
  sender?: { id?: unknown };
  recipient?: { id?: unknown };
  timestamp?: unknown;
};

function extensionFromMediaType(mediaType: string, mime?: string): string {
  const map: Record<string, string> = { image: "jpg", video: "mp4", audio: "mp3", file: "bin" };
  const t = mediaType.trim().toLowerCase();
  if (mime) {
    const m = mime.toLowerCase();
    if (m.includes("jpeg") || m.includes("jpg")) return "jpg";
    if (m.includes("png")) return "png";
    if (m.includes("mp4")) return "mp4";
  }
  return map[t] ?? "bin";
}

function getAttachmentInfo(msg: Record<string, unknown>): { type: string; url: string } | null {
  const attachments = msg.attachments as Array<{ type?: string; payload?: { url?: string } }> | undefined;
  if (!Array.isArray(attachments) || attachments.length === 0) return null;
  const first = attachments[0];
  const url = typeof first?.payload?.url === "string" ? first.payload.url.trim() : "";
  const type = typeof first?.type === "string" ? first.type.trim().toLowerCase() : "file";
  if (!url) return null;
  return { type, url };
}

function getMessageBody(evt: Record<string, unknown>): { body: string; messageType: string } {
  const msg = evt.message as Record<string, unknown> | undefined;
  if (!msg) return { body: "", messageType: "text" };
  if (msg.is_unsupported) return { body: "[Unsupported]", messageType: "unsupported" };
  if (msg.is_deleted) return { body: "[Deleted]", messageType: "text" };
  const text = typeof msg.text === "string" ? msg.text : (msg.text as { text?: string } | undefined)?.text;
  if (text != null && String(text).trim() !== "") return { body: String(text).trim(), messageType: "text" };
  const attachments = msg.attachments as Array<{ type?: string }> | undefined;
  if (Array.isArray(attachments) && attachments.length > 0) {
    const t = attachments[0]?.type ?? "file";
    return { body: `[${t}]`, messageType: t };
  }
  const quickReply = msg.quick_reply as { payload?: string } | undefined;
  if (quickReply?.payload) return { body: String(quickReply.payload), messageType: "quick_reply" };
  return { body: "[message]", messageType: "text" };
}

async function downloadAttachmentToStorage(
  downloadUrl: string,
  accessToken: string,
  supabase: SupabaseClient,
  conversationId: string,
  platformMessageId: string,
  mediaType: string,
): Promise<string | null> {
  try {
    const fileRes = await fetch(downloadUrl, { headers: { Authorization: `Bearer ${accessToken}` } });
    if (!fileRes.ok) return null;
    const contentLength = Number(fileRes.headers.get("content-length") ?? 0);
    const isVideo = mediaType === "video";
    if (isVideo && contentLength > LAZY_VIDEO_BYTES) return null;
    const blob = await fileRes.blob();
    if (isVideo && blob.size > LAZY_VIDEO_BYTES) return null;
    const ext = extensionFromMediaType(mediaType, blob.type);
    const safeId = platformMessageId.replace(/\W/g, "_");
    const path = `fb/inbound/${conversationId}/${safeId}.${ext}`;
    const { error: uploadErr } = await supabase.storage.from(MEDIA_BUCKET).upload(path, blob, {
      contentType: blob.type || undefined,
      upsert: true,
    });
    if (uploadErr) return null;
    const { data: urlData } = supabase.storage.from(MEDIA_BUCKET).getPublicUrl(path);
    return urlData.publicUrl;
  } catch {
    return null;
  }
}

async function extendFacebookMetaSession(
  supabase: SupabaseClient,
  conversationId: string,
  inboundTimestampIso: string,
): Promise<void> {
  const inboundMs = new Date(inboundTimestampIso).getTime();
  if (Number.isNaN(inboundMs)) return;
  const expiresAt = new Date(inboundMs + META_SESSION_MS).toISOString();
  const { data: row } = await supabase
    .from("facebook_conversations")
    .select("meta_session_expires_at")
    .eq("id", conversationId)
    .maybeSingle();
  const prevMs = row?.meta_session_expires_at ? new Date(String(row.meta_session_expires_at)).getTime() : 0;
  const nextMs = new Date(expiresAt).getTime();
  await supabase
    .from("facebook_conversations")
    .update({ meta_session_expires_at: new Date(Math.max(prevMs, nextMs)).toISOString(), updated_at: new Date().toISOString() })
    .eq("id", conversationId);
}

async function fetchMessengerSenderDisplayName(psid: string, pageAccessToken: string): Promise<string | null> {
  const token = pageAccessToken.trim();
  const id = psid.trim();
  if (!token || !id) return null;
  const url =
    `https://graph.facebook.com/${META_GRAPH_VERSION}/${encodeURIComponent(id)}` +
    `?fields=${encodeURIComponent("first_name,last_name,name")}` +
    `&access_token=${encodeURIComponent(token)}`;
  try {
    const res = await fetch(url);
    const data = await res.json().catch(() => ({})) as { name?: string; first_name?: string; last_name?: string };
    if (!res.ok) return null;
    const name = typeof data.name === "string" ? data.name.trim() : "";
    if (name) return name;
    const first = typeof data.first_name === "string" ? data.first_name.trim() : "";
    const last = typeof data.last_name === "string" ? data.last_name.trim() : "";
    const combined = [first, last].filter(Boolean).join(" ").trim();
    return combined || null;
  } catch {
    return null;
  }
}

async function ensureLeadForNewFacebookConversation(
  supabase: SupabaseClient,
  orgId: string,
  convId: string,
  clientName: string,
  title: string,
  pageDisplayName: string,
): Promise<void> {
  const ticketId = "FB-" + String(convId).replace(/-/g, "").slice(0, 8).toUpperCase();
  const { data: existing } = await supabase.from("leads").select("id").eq("ticket_id", ticketId).maybeSingle();
  if (existing) return;
  const { data: unreadStatus } = await supabase
    .from("lead_statuses")
    .select("id")
    .or(`organization_id.eq.${orgId},organization_id.is.null`)
    .eq("name", "Unread")
    .maybeSingle();
  const statusId = unreadStatus?.id ?? null;
  if (!statusId) return;
  await supabase.from("leads").insert({
    ticket_id: ticketId,
    client: (clientName && String(clientName).trim()) || "Messenger",
    title: (title && String(title).trim().slice(0, 100)) || "Messenger",
    category: "",
    created_by: "00000000-0000-0000-0000-000000000000",
    created_by_name: pageDisplayName,
    assignee: "",
    status_id: statusId,
    organization_id: orgId,
    source: "Facebook Messenger",
    services: null,
    followup: 0,
    phone_number: null,
  });
}

export async function resolveFacebookPageByEntryId(
  supabase: SupabaseClient,
  entryId: string | null,
): Promise<FacebookWebhookPage | null> {
  const trimmed = entryId?.trim() ?? "";
  if (!trimmed) return null;

  const { data: page } = await supabase
    .from("organization_facebook_pages")
    .select("organization_id, facebook_page_id, page_name, page_access_token")
    .eq("facebook_page_id", trimmed)
    .eq("is_active", true)
    .limit(1)
    .maybeSingle();
  if (page) return page as FacebookWebhookPage;

  // Page connected via Instagram OAuth only — mirror row may exist on IG table first.
  const { data: igRow } = await supabase
    .from("organization_instagram_accounts")
    .select("organization_id, facebook_page_id, page_access_token, instagram_name")
    .eq("facebook_page_id", trimmed)
    .eq("is_active", true)
    .limit(1)
    .maybeSingle();
  if (!igRow?.facebook_page_id) return null;

  const { data: fbByIgOrg } = await supabase
    .from("organization_facebook_pages")
    .select("organization_id, facebook_page_id, page_name, page_access_token")
    .eq("facebook_page_id", trimmed)
    .eq("organization_id", igRow.organization_id)
    .eq("is_active", true)
    .limit(1)
    .maybeSingle();
  if (fbByIgOrg) return fbByIgOrg as FacebookWebhookPage;

  const token = (igRow.page_access_token as string | null)?.trim() ?? "";
  if (!token) return null;

  return {
    organization_id: igRow.organization_id as string,
    facebook_page_id: String(igRow.facebook_page_id).trim(),
    page_name: (igRow.instagram_name as string | null) ?? null,
    page_access_token: token,
  };
}

/** Resolve Page from webhook entry id and/or messaging recipient (Page PSID). */
export async function resolveFacebookPageForWebhookEntry(
  supabase: SupabaseClient,
  entryId: string | null,
  messaging: MessagingEvt[],
): Promise<FacebookWebhookPage | null> {
  const candidates = new Set<string>();
  const entryTrimmed = entryId?.trim() ?? "";
  if (entryTrimmed) candidates.add(entryTrimmed);
  for (const evt of messaging) {
    const recipientId = evt.recipient?.id != null ? String(evt.recipient.id).trim() : "";
    if (recipientId) candidates.add(recipientId);
  }
  for (const id of candidates) {
    const page = await resolveFacebookPageByEntryId(supabase, id);
    if (page) return page;
  }
  return null;
}

async function handleFacebookReadReceipt(
  supabase: SupabaseClient,
  convId: string,
  read: { watermark?: unknown; mid?: unknown },
): Promise<void> {
  const now = new Date().toISOString();

  if (read.mid != null) {
    const mid = String(read.mid).trim();
    if (mid) {
      await supabase
        .from("facebook_messages")
        .update({ status: "read", status_updated_at: now, read_at: now })
        .eq("conversation_id", convId)
        .eq("platform_message_id", mid)
        .eq("direction", "outbound");
    }
  }

  if (read.watermark != null) {
    const wmMs = Number(read.watermark);
    if (Number.isFinite(wmMs) && wmMs > 0) {
      const wmIso = new Date(wmMs).toISOString();
      await supabase
        .from("facebook_messages")
        .update({ status: "read", status_updated_at: now, read_at: now })
        .eq("conversation_id", convId)
        .eq("direction", "outbound")
        .lte("created_at", wmIso);
    }
  }

  const { data: conv } = await supabase
    .from("facebook_conversations")
    .select("last_message_direction")
    .eq("id", convId)
    .maybeSingle();
  if (conv?.last_message_direction === "outbound") {
    await supabase
      .from("facebook_conversations")
      .update({ last_message_status: "read", updated_at: now })
      .eq("id", convId);
  }
}

export async function processFacebookMessengerEvents(
  supabase: SupabaseClient,
  page: FacebookWebhookPage,
  messaging: MessagingEvt[],
  notifyPush: (record: Record<string, unknown>) => Promise<void>,
  ensuredLivechatStatusOrgs: Set<string>,
): Promise<number> {
  let processedCount = 0;
  const orgId = page.organization_id;
  const pageId = String(page.facebook_page_id).trim();
  const accessToken = (page.page_access_token ?? "").trim() || null;
  const displayName = (page.page_name ?? "").trim() || pageId;

  if (!ensuredLivechatStatusOrgs.has(orgId)) {
    const { error } = await supabase.rpc("ensure_livechat_lead_statuses_for_org", { p_organization_id: orgId });
    if (!error) ensuredLivechatStatusOrgs.add(orgId);
  }

  for (const evt of messaging) {
    const senderId = evt.sender?.id != null ? String(evt.sender.id) : null;
    const ts = evt.timestamp != null ? new Date(Number(evt.timestamp)).toISOString() : new Date().toISOString();

    if (evt.message?.is_echo) continue;

    if (evt.postback && !evt.message) {
      if (!senderId) continue;
      const payload = typeof evt.postback.payload === "string" ? evt.postback.payload.trim() : "";
      const title = typeof evt.postback.title === "string" ? evt.postback.title.trim() : "";
      const bodyText = payload || title || "[Postback]";
      const mid = `postback_${senderId}_${String(evt.timestamp ?? Date.now())}`;
      const convId = await upsertFacebookConversationInbound(
        supabase, orgId, pageId, senderId, bodyText, ts, accessToken, displayName,
      );
      if (convId) {
        const pbPayload = {
          conversation_id: convId,
          direction: "inbound",
          platform_message_id: mid,
          body: bodyText,
          message_type: "postback",
          raw_metadata: evt,
          created_at: ts,
        };
        await supabase.from("facebook_messages").insert(pbPayload);
        await notifyPush(pbPayload);
        processedCount += 1;

        if (payload.startsWith(LEAD_MAGNET_PAYLOAD_PREFIX) && accessToken && convId) {
          scheduleLeadMagnetPostbackTrigger({
            platform: "facebook",
            organizationId: orgId,
            accountId: pageId,
            participantScopedId: senderId,
            participantUsername: displayName,
            payload,
            conversationId: convId,
            accessToken,
            pageId,
          });
        }
      }
      continue;
    }

    // Read / seen receipts (message_reads + messaging_seen subscriptions)
    if ((evt.read || evt.seen) && !evt.message && !evt.postback) {
      const customerPsid = senderId;
      if (!customerPsid) continue;
      const readPayload = (evt.read ?? evt.seen) as { watermark?: unknown; mid?: unknown };
      const { data: convForRead } = await supabase
        .from("facebook_conversations")
        .select("id")
        .eq("organization_id", orgId)
        .eq("facebook_page_id", pageId)
        .eq("customer_psid", customerPsid)
        .maybeSingle();
      if (convForRead?.id) {
        await handleFacebookReadReceipt(supabase, convForRead.id, readPayload);
        processedCount += 1;
      }
      continue;
    }

    const mid = evt.message?.mid != null ? String(evt.message.mid) : null;
    if (!senderId || !mid) continue;

    const { body: bodyText, messageType } = getMessageBody(evt as Record<string, unknown>);
    const lastBody = bodyText.slice(0, 200);

    const { data: existingConv } = await supabase
      .from("facebook_conversations")
      .select("id, first_inbound_at, customer_name")
      .eq("organization_id", orgId)
      .eq("facebook_page_id", pageId)
      .eq("customer_psid", senderId)
      .maybeSingle();

    const existingName = (existingConv as { customer_name?: string | null } | null)?.customer_name?.trim() ?? "";
    let customerName = existingName || null;
    if (!customerName && accessToken) {
      customerName = await fetchMessengerSenderDisplayName(senderId, accessToken);
    }

    let conv: { id: string; first_inbound_at: string | null } | null = null;
    if (existingConv?.id) {
      const { data: updated } = await supabase
        .from("facebook_conversations")
        .update({
          last_message_at: ts,
          last_message_body: lastBody,
          last_message_direction: "inbound",
          last_inbound_at: ts,
          updated_at: ts,
          ...(customerName && !existingName ? { customer_name: customerName } : {}),
        })
        .eq("id", existingConv.id)
        .select("id, first_inbound_at")
        .single();
      conv = updated;
    } else {
      const newConvId = crypto.randomUUID();
      const ticketId = "FB-" + newConvId.replace(/-/g, "").slice(0, 8).toUpperCase();
      const orgOrGlobal = `organization_id.eq.${orgId},organization_id.is.null`;
      const { data: openStatus } = await supabase.from("lead_statuses").select("id").or(orgOrGlobal).eq("name", "Open").maybeSingle();
      const { data: unreadStatus } = openStatus?.id
        ? { data: null }
        : await supabase.from("lead_statuses").select("id").or(orgOrGlobal).eq("name", "Unread").maybeSingle();
      const leadStatusId = openStatus?.id ?? unreadStatus?.id ?? null;
      const { data: inserted, error: insertErr } = await supabase
        .from("facebook_conversations")
        .insert({
          id: newConvId,
          organization_id: orgId,
          facebook_page_id: pageId,
          customer_psid: senderId,
          customer_external_id: senderId,
          ticket_id: ticketId,
          lead_status_id: leadStatusId,
          last_message_at: ts,
          last_message_body: lastBody,
          last_message_direction: "inbound",
          last_inbound_at: ts,
          first_inbound_at: ts,
          updated_at: ts,
          ...(customerName ? { customer_name: customerName } : {}),
        })
        .select("id, first_inbound_at")
        .single();
      if (insertErr) continue;
      conv = inserted;
      await ensureLeadForNewFacebookConversation(
        supabase, orgId, conv!.id, customerName || "Messenger contact", lastBody || "Messenger", displayName,
      );
      await supabase.from("facebook_conversation_cycles").insert({ conversation_id: conv!.id, cycle_started_at: ts });
    }

    if (!conv) continue;
    await extendFacebookMetaSession(supabase, conv.id, ts);

    let mediaUrl: string | null = null;
    const msgRecord = (evt as Record<string, unknown>).message as Record<string, unknown> | undefined;
    const attachmentInfo = msgRecord ? getAttachmentInfo(msgRecord) : null;
    if (attachmentInfo && accessToken && ["image", "video"].includes(attachmentInfo.type)) {
      mediaUrl = await downloadAttachmentToStorage(
        attachmentInfo.url, accessToken, supabase, conv.id, mid, attachmentInfo.type,
      );
    }

    const insertPayload: Record<string, unknown> = {
      conversation_id: conv.id,
      direction: "inbound",
      platform_message_id: mid,
      body: bodyText,
      message_type: messageType,
      raw_metadata: evt,
      created_at: ts,
    };
    if (mediaUrl) insertPayload.media_url = mediaUrl;

    const { error: msgErr } = await supabase.from("facebook_messages").insert(insertPayload);
    if (msgErr) continue;
    await notifyPush(insertPayload);

    if (existingConv) {
      await reopenFacebookConversationIfNeeded(supabase, orgId, conv.id, ts);
    }

    processedCount += 1;
  }

  return processedCount;
}

async function upsertFacebookConversationInbound(
  supabase: SupabaseClient,
  orgId: string,
  pageId: string,
  senderId: string,
  bodyText: string,
  ts: string,
  accessToken: string | null,
  pageDisplayName: string,
): Promise<string | null> {
  const { data: existing } = await supabase
    .from("facebook_conversations")
    .select("id")
    .eq("organization_id", orgId)
    .eq("facebook_page_id", pageId)
    .eq("customer_psid", senderId)
    .maybeSingle();
  if (existing?.id) {
    await extendFacebookMetaSession(supabase, existing.id, ts);
    await supabase
      .from("facebook_conversations")
      .update({
        last_message_at: ts,
        last_message_body: bodyText.slice(0, 200),
        last_message_direction: "inbound",
        last_inbound_at: ts,
        updated_at: ts,
      })
      .eq("id", existing.id);
    return existing.id;
  }
  const newConvId = crypto.randomUUID();
  const ticketId = "FB-" + newConvId.replace(/-/g, "").slice(0, 8).toUpperCase();
  const orgOrGlobal = `organization_id.eq.${orgId},organization_id.is.null`;
  const { data: openSt } = await supabase.from("lead_statuses").select("id").or(orgOrGlobal).eq("name", "Open").maybeSingle();
  const { data: unreadSt } = openSt?.id
    ? { data: null }
    : await supabase.from("lead_statuses").select("id").or(orgOrGlobal).eq("name", "Unread").maybeSingle();
  let customerName: string | null = null;
  if (accessToken) customerName = await fetchMessengerSenderDisplayName(senderId, accessToken);
  const { data: inserted } = await supabase
    .from("facebook_conversations")
    .insert({
      id: newConvId,
      organization_id: orgId,
      facebook_page_id: pageId,
      customer_psid: senderId,
      customer_external_id: senderId,
      ticket_id: ticketId,
      lead_status_id: openSt?.id ?? unreadSt?.id ?? null,
      last_message_at: ts,
      last_message_body: bodyText.slice(0, 200),
      last_message_direction: "inbound",
      last_inbound_at: ts,
      first_inbound_at: ts,
      updated_at: ts,
      ...(customerName ? { customer_name: customerName } : {}),
    })
    .select("id")
    .single();
  if (!inserted?.id) return null;
  await ensureLeadForNewFacebookConversation(
    supabase, orgId, inserted.id, customerName || "Messenger contact", bodyText, pageDisplayName,
  );
  await supabase.from("facebook_conversation_cycles").insert({ conversation_id: inserted.id, cycle_started_at: ts });
  return inserted.id;
}

async function reopenFacebookConversationIfNeeded(
  supabase: SupabaseClient,
  orgId: string,
  convId: string,
  ts: string,
): Promise<void> {
  const { data: convRow } = await supabase
    .from("facebook_conversations")
    .select("lead_status_id, organization_id, ticket_id")
    .eq("id", convId)
    .single();
  const statusId = convRow?.lead_status_id ?? null;
  let leadStatusName: string | null = null;
  if (statusId) {
    const { data: statusRow } = await supabase.from("lead_statuses").select("name").eq("id", statusId).maybeSingle();
    leadStatusName = (statusRow?.name as string) ?? null;
  }
  const orgOrGlobal = `organization_id.eq.${orgId},organization_id.is.null`;
  const { data: openStatus } = await supabase.from("lead_statuses").select("id").or(orgOrGlobal).eq("name", "Open").maybeSingle();
  const { data: unreadStatus } = openStatus?.id
    ? { data: null }
    : await supabase.from("lead_statuses").select("id").or(orgOrGlobal).eq("name", "Unread").maybeSingle();
  const openStatusId = openStatus?.id ?? unreadStatus?.id ?? null;
  const statusNameLower = leadStatusName?.trim().toLowerCase() ?? "";
  const isResolved = statusNameLower === "closed" || statusNameLower === "resolve";
  const isExpired = statusNameLower === "expired";
  if (!openStatusId || !(statusId == null || isResolved || isExpired)) return;
  await supabase
    .from("facebook_conversations")
    .update({ lead_status_id: openStatusId, last_inbound_at: ts, updated_at: ts })
    .eq("id", convId);
  if (convRow?.organization_id) {
    const ticketId =
      (convRow.ticket_id as string) ?? `FB-${convId.replace(/-/g, "").slice(0, 8).toUpperCase()}`;
    await supabase
      .from("leads")
      .update({ status_id: openStatusId, updated_at: ts })
      .eq("organization_id", convRow.organization_id)
      .eq("ticket_id", ticketId);
  }
  await supabase.from("facebook_conversation_cycles").insert({ conversation_id: convId, cycle_started_at: ts });
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { isLikelyInstagramBusinessAccountId } from "./instagramAccountDedupe.ts";
import { metaGraphVersion } from "./metaPlatformScopes.ts";

type ConversationParticipant = { id?: string; username?: string; name?: string };

function uniqueIds(ids: Array<string | null | undefined>): string[] {
  return [...new Set(ids.map((id) => (id ?? "").trim()).filter(Boolean))];
}

/**
 * Echo DMs from another connected IG professional account may store the sender as
 * instagram_business_account_id. Meta Send API requires the Instagram-scoped ID (IGSID)
 * from the Page conversation thread — resolve via Graph conversations when needed.
 */
export async function resolveInstagramDmRecipientId(
  supabase: SupabaseClient,
  orgId: string,
  inboxIgBusinessAccountId: string,
  storedCustomerId: string,
  pageId: string,
  pageToken: string,
  options?: { altCustomerIds?: string[] },
): Promise<string> {
  const primary = storedCustomerId.trim();
  const inboxId = inboxIgBusinessAccountId.trim();
  const page = pageId.trim();
  const token = pageToken.trim();
  if (!primary || !inboxId || !page || !token) return primary;

  const candidateIds = uniqueIds([primary, ...(options?.altCustomerIds ?? [])]);
  let linkedBusinessId: string | null = null;
  let targetUsername = "";

  for (const cid of candidateIds) {
    const { data: linkedAcc } = await supabase
      .from("organization_instagram_accounts")
      .select("instagram_business_account_id, instagram_username")
      .eq("organization_id", orgId)
      .eq("instagram_business_account_id", cid)
      .eq("is_active", true)
      .maybeSingle();

    if (linkedAcc) {
      linkedBusinessId = cid;
      targetUsername = (linkedAcc.instagram_username ?? "").trim().toLowerCase();
      break;
    }
  }

  if (!linkedBusinessId) {
    return primary;
  }

  for (const probeId of candidateIds) {
    const viaUserFilter = await lookupParticipantViaUserIdConversation(
      page,
      token,
      inboxId,
      probeId,
      targetUsername,
      linkedBusinessId,
    );
    if (viaUserFilter && viaUserFilter !== linkedBusinessId) {
      console.log("[instagramMessagingRecipient] resolved via user_id conversation filter", {
        businessId: linkedBusinessId,
        igsid: viaUserFilter,
        probeId,
      });
      return viaUserFilter;
    }
  }

  const resolvedFromScan = await lookupParticipantIgsidFromPageConversations(
    page,
    token,
    inboxId,
    targetUsername,
    linkedBusinessId,
  );
  if (resolvedFromScan && resolvedFromScan !== linkedBusinessId) {
    console.log("[instagramMessagingRecipient] resolved connected account to IGSID", {
      businessId: linkedBusinessId,
      igsid: resolvedFromScan,
      username: targetUsername,
    });
    return resolvedFromScan;
  }

  return primary;
}

/** Resolve with retries — Page conversations may lag a few seconds after first inbound webhook. */
export async function resolveInstagramDmRecipientIdWithRetry(
  supabase: SupabaseClient,
  orgId: string,
  inboxIgBusinessAccountId: string,
  storedCustomerId: string,
  pageId: string,
  pageToken: string,
  options?: { altCustomerIds?: string[]; attempts?: number; delayMs?: number },
): Promise<string> {
  const attempts = Math.max(1, options?.attempts ?? 3);
  const delayMs = options?.delayMs ?? 700;
  const candidateIds = uniqueIds([storedCustomerId, ...(options?.altCustomerIds ?? [])]);

  let linkedBusinessId: string | null = null;
  for (const cid of candidateIds) {
    const { data: linkedAcc } = await supabase
      .from("organization_instagram_accounts")
      .select("instagram_business_account_id")
      .eq("organization_id", orgId)
      .eq("instagram_business_account_id", cid)
      .eq("is_active", true)
      .maybeSingle();
    if (linkedAcc) {
      linkedBusinessId = cid;
      break;
    }
  }

  if (!linkedBusinessId) {
    return storedCustomerId.trim();
  }

  let last = storedCustomerId.trim();
  for (let i = 0; i < attempts; i++) {
    last = await resolveInstagramDmRecipientId(
      supabase,
      orgId,
      inboxIgBusinessAccountId,
      storedCustomerId,
      pageId,
      pageToken,
      options,
    );
    if (last !== linkedBusinessId && !isLikelyInstagramBusinessAccountId(last)) {
      return last;
    }
    if (i < attempts - 1) {
      await new Promise((r) => setTimeout(r, delayMs));
    }
  }
  return last;
}

async function lookupParticipantViaUserIdConversation(
  pageId: string,
  pageToken: string,
  inboxIgBusinessAccountId: string,
  userId: string,
  targetUsername: string,
  linkedBusinessId: string,
): Promise<string | null> {
  try {
    const url =
      `https://graph.facebook.com/${metaGraphVersion()}/${encodeURIComponent(pageId)}/conversations` +
      `?platform=instagram&user_id=${encodeURIComponent(userId)}&fields=participants&limit=10` +
      `&access_token=${encodeURIComponent(pageToken)}`;
    const res = await fetch(url);
    const data = await res.json().catch(() => ({})) as {
      data?: Array<{ participants?: { data?: ConversationParticipant[] } }>;
      error?: { message?: string };
    };
    if (!res.ok) {
      console.warn("[instagramMessagingRecipient] user_id conversation filter error", data.error?.message);
      return null;
    }

    for (const thread of data.data ?? []) {
      const resolved = pickMessagingParticipantFromThread(
        thread.participants?.data ?? [],
        inboxIgBusinessAccountId,
        targetUsername,
        linkedBusinessId,
      );
      if (resolved) return resolved;
    }
  } catch (e) {
    console.warn("[instagramMessagingRecipient] user_id conversation lookup failed", e);
  }
  return null;
}

function pickMessagingParticipantFromThread(
  participants: ConversationParticipant[],
  inboxIgBusinessAccountId: string,
  targetUsername: string,
  linkedBusinessId: string,
): string | null {
  const includesInbox = participants.some((p) => String(p.id ?? "").trim() === inboxIgBusinessAccountId);
  const includesLinked = participants.some((p) => String(p.id ?? "").trim() === linkedBusinessId);

  if (!includesInbox && !includesLinked) return null;

  for (const p of participants) {
    const pid = p.id != null ? String(p.id).trim() : "";
    const pun = (p.username ?? "").trim().toLowerCase();
    if (!pid || pid === inboxIgBusinessAccountId || pid === linkedBusinessId) continue;
    if (targetUsername && pun === targetUsername) return pid;
    if (!isLikelyInstagramBusinessAccountId(pid)) return pid;
  }
  return null;
}

async function lookupParticipantIgsidFromPageConversations(
  pageId: string,
  pageToken: string,
  inboxIgBusinessAccountId: string,
  targetUsername: string,
  linkedBusinessId: string,
): Promise<string | null> {
  try {
    let nextUrl: string | null =
      `https://graph.facebook.com/${metaGraphVersion()}/${encodeURIComponent(pageId)}/conversations` +
      `?platform=instagram&fields=participants&limit=50` +
      `&access_token=${encodeURIComponent(pageToken)}`;

    for (let page = 0; page < 5 && nextUrl; page++) {
      const res = await fetch(nextUrl);
      const data = await res.json().catch(() => ({})) as {
        data?: Array<{ participants?: { data?: ConversationParticipant[] } }>;
        paging?: { next?: string };
        error?: { message?: string };
      };
      if (!res.ok) {
        console.warn("[instagramMessagingRecipient] conversations API error", data.error?.message);
        break;
      }

      for (const thread of data.data ?? []) {
        const resolved = pickMessagingParticipantFromThread(
          thread.participants?.data ?? [],
          inboxIgBusinessAccountId,
          targetUsername,
          linkedBusinessId,
        );
        if (resolved) return resolved;
      }

      nextUrl = data.paging?.next ?? null;
    }
  } catch (e) {
    console.warn("[instagramMessagingRecipient] conversations lookup failed", e);
  }
  return null;
}

export { isLikelyInstagramBusinessAccountId };

/** Instagram Business Account IDs from Graph API typically start with 178414. */
export function isLikelyInstagramBusinessAccountId(id: string): boolean {
  const trimmed = id.trim();
  return /^178414\d+$/.test(trimmed);
}

export function pickCanonicalInstagramBusinessAccountId(candidates: readonly string[]): string {
  const unique = [...new Set(candidates.map((c) => c.trim()).filter(Boolean))];
  if (unique.length === 0) return "";
  const preferred = unique.filter(isLikelyInstagramBusinessAccountId);
  const pool = preferred.length > 0 ? preferred : unique;
  return pool.sort((a, b) => b.length - a.length)[0] ?? unique[0];
}

export function normalizeInstagramUsername(username: string | null | undefined): string {
  return (username ?? "").trim().replace(/^@+/i, "").toLowerCase();
}

/** Stable customer identity: @username > external (webhook sender) > ig id. Username survives Meta ID drift. */
export function instagramConversationCustomerDedupeKey(
  customerIgId: string | null | undefined,
  customerExternalId: string | null | undefined,
  customerName: string | null | undefined,
): string {
  const username = normalizeInstagramUsername(
    (customerName ?? "").trim().startsWith("@") ? customerName : null,
  );
  if (username) return username;

  const external = (customerExternalId ?? "").trim().toLowerCase();
  if (external) return external;

  const ig = (customerIgId ?? "").trim().toLowerCase();
  if (ig) return ig;

  return "";
}

export function instagramCustomerIdentityTokens(
  customerIgId: string | null | undefined,
  customerExternalId: string | null | undefined,
  customerName: string | null | undefined,
): Set<string> {
  const tokens = new Set<string>();
  const ig = (customerIgId ?? "").trim().toLowerCase();
  const ext = (customerExternalId ?? "").trim().toLowerCase();
  if (ig) tokens.add(ig);
  if (ext) tokens.add(ext);
  const name = (customerName ?? "").trim();
  if (name.startsWith("@")) tokens.add(`@${name.slice(1).toLowerCase()}`);
  return tokens;
}

export function instagramCustomerIdentitiesOverlap(
  a: {
    customer_ig_id: string;
    customer_external_id?: string | null;
    customer_name?: string | null;
  },
  b: {
    customer_ig_id: string;
    customer_external_id?: string | null;
    customer_name?: string | null;
  },
): boolean {
  const ta = instagramCustomerIdentityTokens(a.customer_ig_id, a.customer_external_id, a.customer_name);
  const tb = instagramCustomerIdentityTokens(b.customer_ig_id, b.customer_external_id, b.customer_name);
  for (const t of ta) {
    if (tb.has(t)) return true;
  }
  return false;
}

export type InstagramConvMergeRow = {
  id: string;
  first_inbound_at: string | null;
  customer_name: string | null;
  customer_ig_id: string;
  customer_external_id?: string | null;
  last_message_at?: string | null;
  updated_at?: string | null;
  created_at?: string | null;
};

function pickBestMessagingCustomerId(ids: string[]): string {
  const unique = [...new Set(ids.map((id) => id.trim()).filter(Boolean))];
  if (unique.length === 0) return "";
  const nonBusiness = unique.filter((id) => !isLikelyInstagramBusinessAccountId(id));
  if (nonBusiness.length > 0) return nonBusiness.sort((a, b) => b.length - a.length)[0];
  return unique.sort((a, b) => b.length - a.length)[0];
}

function scoreInstagramConvKeeper(row: InstagramConvMergeRow): number {
  let score = 0;
  if (row.customer_name?.trim()) score += 20;
  if (row.customer_external_id?.trim()) score += 10;
  if (!isLikelyInstagramBusinessAccountId(row.customer_ig_id)) score += 5;
  if (row.last_message_at) score += 1;
  return score;
}

type SupabaseMergeClient = {
  from: (table: string) => {
    select: (cols: string) => {
      eq: (col: string, val: string) => {
        eq: (col2: string, val2: string) => Promise<{ data: unknown[] | null }>;
        maybeSingle: () => Promise<{ data: Record<string, unknown> | null }>;
      };
    };
    update: (row: Record<string, unknown>) => {
      eq: (col: string, val: string) => Promise<{ error: { message?: string } | null }>;
    };
    delete: () => {
      eq: (col: string, val: string) => Promise<{ error: { message?: string } | null }>;
    };
  };
};

/** Merge duplicate IG threads (IGSID vs business account id drift) into one conversation row. */
export async function mergeInstagramConversationDuplicates(
  supabase: SupabaseMergeClient,
  rows: InstagramConvMergeRow[],
): Promise<InstagramConvMergeRow> {
  if (rows.length === 0) {
    throw new Error("mergeInstagramConversationDuplicates: no rows");
  }
  if (rows.length === 1) return rows[0];

  const sorted = [...rows].sort((a, b) => {
    const scoreDiff = scoreInstagramConvKeeper(b) - scoreInstagramConvKeeper(a);
    if (scoreDiff !== 0) return scoreDiff;
    const at = a.last_message_at ? new Date(a.last_message_at).getTime() : 0;
    const bt = b.last_message_at ? new Date(b.last_message_at).getTime() : 0;
    return bt - at;
  });
  const keeper = sorted[0];
  const dupes = sorted.slice(1);

  const allIgIds = sorted.map((r) => r.customer_ig_id);
  const allExternal = sorted.map((r) => r.customer_external_id ?? "");
  const bestName = sorted.find((r) => r.customer_name?.trim())?.customer_name ?? keeper.customer_name;
  const messagingId = pickBestMessagingCustomerId(allIgIds);
  const externalId =
    allExternal.map((v) => v.trim()).find(Boolean) ??
    allIgIds.map((v) => v.trim()).find((id) => id && id !== messagingId) ??
    "";

  for (const dup of dupes) {
    await supabase
      .from("instagram_messages")
      .update({ conversation_id: keeper.id })
      .eq("conversation_id", dup.id);

    await supabase.from("instagram_conversation_cycles").delete().eq("conversation_id", dup.id);

    const { error: delErr } = await supabase.from("instagram_conversations").delete().eq("id", dup.id);
    if (delErr) {
      console.error("mergeInstagramConversationDuplicates: delete failed", dup.id, delErr);
    }
  }

  await supabase
    .from("instagram_conversations")
    .update({
      customer_ig_id: messagingId || keeper.customer_ig_id,
      ...(externalId ? { customer_external_id: externalId } : {}),
      ...(bestName?.trim() ? { customer_name: bestName.trim() } : {}),
      updated_at: new Date().toISOString(),
    })
    .eq("id", keeper.id);

  return {
    ...keeper,
    customer_ig_id: messagingId || keeper.customer_ig_id,
    customer_external_id: externalId || keeper.customer_external_id,
    customer_name: bestName ?? keeper.customer_name,
  };
}

type SupabaseAdmin = {
  from: (table: string) => {
    select: (cols: string) => {
      eq: (col: string, val: string) => {
        eq: (col2: string, val2: boolean) => Promise<{ data: unknown[] | null }>;
      };
    };
    update: (row: Record<string, unknown>) => {
      eq: (col: string, val: string) => Promise<{ error: { message?: string } | null }>;
    };
  };
};

/** Deactivate duplicate active rows that share the same @username (Meta FBE sometimes returns two business IDs). */
export async function dedupeOrganizationInstagramAccountsByUsername(
  supabaseAdmin: SupabaseAdmin,
  orgId: string,
): Promise<number> {
  const { data } = await supabaseAdmin
    .from("organization_instagram_accounts")
    .select("id, instagram_business_account_id, instagram_username, updated_at, created_at")
    .eq("organization_id", orgId)
    .eq("is_active", true);

  const rows = (data ?? []) as Array<{
    id: string;
    instagram_business_account_id: string;
    instagram_username: string | null;
    updated_at?: string;
    created_at?: string;
  }>;

  const byUsername = new Map<string, typeof rows>();
  for (const row of rows) {
    const uname = normalizeInstagramUsername(row.instagram_username);
    if (!uname) continue;
    const list = byUsername.get(uname) ?? [];
    list.push(row);
    byUsername.set(uname, list);
  }

  let deactivated = 0;
  for (const [, group] of byUsername) {
    if (group.length <= 1) continue;
    const sorted = [...group].sort((a, b) => {
      const aCanon = isLikelyInstagramBusinessAccountId(a.instagram_business_account_id) ? 0 : 1;
      const bCanon = isLikelyInstagramBusinessAccountId(b.instagram_business_account_id) ? 0 : 1;
      if (aCanon !== bCanon) return aCanon - bCanon;
      return (b.updated_at ?? b.created_at ?? "").localeCompare(a.updated_at ?? a.created_at ?? "");
    });
    for (const dup of sorted.slice(1)) {
      const { error } = await supabaseAdmin
        .from("organization_instagram_accounts")
        .update({ is_active: false, updated_at: new Date().toISOString() })
        .eq("id", dup.id);
      if (!error) deactivated += 1;
    }
  }
  return deactivated;
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import type { MetaContentPlatform } from "./metaContentAuth.ts";

export type MetaInboxPostStateRow = {
  media_id: string;
  last_known_comment_count: number;
  is_highlighted: boolean;
  pinned_at: string | null;
};

export type MetaInboxInboundCommentRow = {
  media_id: string;
  comment_id: string;
  detected_at: string;
};

export type MetaManageCommentsInboxState = {
  posts: MetaInboxPostStateRow[];
  inbound_comments: MetaInboxInboundCommentRow[];
  engaged_comment_ids: string[];
};

type PostBaselineInput = { media_id: string; comment_count: number };

function accountKey(platform: MetaContentPlatform, accountId: string) {
  return { platform, account_id: accountId };
}

export async function getMetaManageCommentsInboxState(
  admin: SupabaseClient,
  organizationId: string,
  platform: MetaContentPlatform,
  accountId: string,
): Promise<MetaManageCommentsInboxState> {
  const key = accountKey(platform, accountId);
  const [postsRes, inboundRes, engagedRes] = await Promise.all([
    admin.from("meta_manage_comments_post_inbox_state").select("*")
      .eq("organization_id", organizationId).eq("platform", key.platform).eq("account_id", key.account_id),
    admin.from("meta_manage_comments_inbound_comments").select("*")
      .eq("organization_id", organizationId).eq("platform", key.platform).eq("account_id", key.account_id),
    admin.from("meta_manage_comments_comment_engagements").select("comment_id")
      .eq("organization_id", organizationId).eq("platform", key.platform).eq("account_id", key.account_id),
  ]);
  if (postsRes.error) throw new Error(postsRes.error.message);
  if (inboundRes.error) throw new Error(inboundRes.error.message);
  if (engagedRes.error) throw new Error(engagedRes.error.message);

  return {
    posts: (postsRes.data ?? []).map((row) => ({
      media_id: String(row.media_id),
      last_known_comment_count: Number(row.last_known_comment_count ?? 0),
      is_highlighted: Boolean(row.is_highlighted),
      pinned_at: row.pinned_at ?? null,
    })),
    inbound_comments: (inboundRes.data ?? []).map((row) => ({
      media_id: String(row.media_id),
      comment_id: String(row.comment_id),
      detected_at: String(row.detected_at),
    })),
    engaged_comment_ids: (engagedRes.data ?? []).map((row) => String(row.comment_id)),
  };
}

async function clearInboundForMedia(
  admin: SupabaseClient,
  organizationId: string,
  platform: MetaContentPlatform,
  accountId: string,
  mediaIds: string[],
): Promise<void> {
  if (mediaIds.length === 0) return;
  const { error } = await admin
    .from("meta_manage_comments_inbound_comments")
    .delete()
    .eq("organization_id", organizationId)
    .eq("platform", platform)
    .eq("account_id", accountId)
    .in("media_id", mediaIds);
  if (error) throw new Error(error.message);
}

export async function syncMetaManageCommentsPostBaselines(
  admin: SupabaseClient,
  organizationId: string,
  platform: MetaContentPlatform,
  accountId: string,
  posts: PostBaselineInput[],
): Promise<MetaManageCommentsInboxState> {
  if (posts.length === 0) {
    return getMetaManageCommentsInboxState(admin, organizationId, platform, accountId);
  }

  const mediaIds = posts.map((p) => p.media_id);
  const { data: existingRows, error: fetchErr } = await admin
    .from("meta_manage_comments_post_inbox_state")
    .select("*")
    .eq("organization_id", organizationId)
    .eq("platform", platform)
    .eq("account_id", accountId)
    .in("media_id", mediaIds);
  if (fetchErr) throw new Error(fetchErr.message);

  const existingByMedia = new Map((existingRows ?? []).map((row) => [String(row.media_id), row]));
  const now = new Date().toISOString();

  const upserts = posts.map((post) => {
    const prev = existingByMedia.get(post.media_id);
    const prevCount = prev != null ? Number(prev.last_known_comment_count ?? 0) : null;
    const countIncreased = prevCount != null && post.comment_count > prevCount;
    const isNew = prev == null;
    let isHighlighted = Boolean(prev?.is_highlighted);
    let pinnedAt: string | null = prev?.pinned_at ?? null;
    if (post.comment_count === 0) {
      isHighlighted = false;
      pinnedAt = null;
    } else if (countIncreased) {
      isHighlighted = true;
      pinnedAt = now;
    } else if (isNew && post.comment_count > 0) {
      isHighlighted = false;
    }
    return {
      organization_id: organizationId,
      platform,
      account_id: accountId,
      media_id: post.media_id,
      last_known_comment_count: post.comment_count,
      is_highlighted: isHighlighted,
      thread_comments_seeded: Boolean(prev?.thread_comments_seeded),
      pinned_at: pinnedAt,
      updated_at: now,
    };
  });

  const { error: upsertErr } = await admin
    .from("meta_manage_comments_post_inbox_state")
    .upsert(upserts, { onConflict: "organization_id,platform,account_id,media_id" });
  if (upsertErr) throw new Error(upsertErr.message);

  await clearInboundForMedia(
    admin,
    organizationId,
    platform,
    accountId,
    posts.filter((p) => p.comment_count === 0).map((p) => p.media_id),
  );

  return getMetaManageCommentsInboxState(admin, organizationId, platform, accountId);
}

export async function syncMetaManageCommentsInboundComments(
  admin: SupabaseClient,
  organizationId: string,
  platform: MetaContentPlatform,
  accountId: string,
  mediaId: string,
  commentIds: string[],
): Promise<MetaManageCommentsInboxState> {
  const uniqueIds = [...new Set(commentIds.map((id) => id.trim()).filter(Boolean))];
  const now = new Date().toISOString();

  if (uniqueIds.length === 0) {
    await clearInboundForMedia(admin, organizationId, platform, accountId, [mediaId]);
    const { data: postRow } = await admin
      .from("meta_manage_comments_post_inbox_state")
      .select("last_known_comment_count")
      .eq("organization_id", organizationId)
      .eq("platform", platform)
      .eq("account_id", accountId)
      .eq("media_id", mediaId)
      .maybeSingle();
    await admin.from("meta_manage_comments_post_inbox_state").upsert({
      organization_id: organizationId,
      platform,
      account_id: accountId,
      media_id: mediaId,
      last_known_comment_count: Number(postRow?.last_known_comment_count ?? 0),
      is_highlighted: false,
      thread_comments_seeded: true,
      pinned_at: null,
      updated_at: now,
    }, { onConflict: "organization_id,platform,account_id,media_id" });
    return getMetaManageCommentsInboxState(admin, organizationId, platform, accountId);
  }

  const rows = uniqueIds.map((commentId) => ({
    organization_id: organizationId,
    platform,
    account_id: accountId,
    media_id: mediaId,
    comment_id: commentId,
    detected_at: now,
  }));
  const { error } = await admin
    .from("meta_manage_comments_inbound_comments")
    .upsert(rows, { onConflict: "organization_id,platform,account_id,media_id,comment_id", ignoreDuplicates: true });
  if (error) throw new Error(error.message);

  await admin.from("meta_manage_comments_post_inbox_state").upsert({
    organization_id: organizationId,
    platform,
    account_id: accountId,
    media_id: mediaId,
    is_highlighted: true,
    pinned_at: now,
    thread_comments_seeded: true,
    updated_at: now,
  }, { onConflict: "organization_id,platform,account_id,media_id" });

  return getMetaManageCommentsInboxState(admin, organizationId, platform, accountId);
}

export async function dismissMetaManageCommentsPostHighlight(
  admin: SupabaseClient,
  organizationId: string,
  platform: MetaContentPlatform,
  accountId: string,
  mediaId: string,
): Promise<MetaManageCommentsInboxState> {
  const now = new Date().toISOString();
